func (u AIChannelBaseUpdate) ApplyTo(x *BaseAIChannel) error {
	if u.Name != nil {
		x.Name = *u.Name
	}
	if u.Disabled != nil {
		x.Disabled = *u.Disabled
	}
	if u.Channel != nil {
		x.Channel = *u.Channel
	}
	if u.Device != nil {
		x.Device = *u.Device
	}
	return nil
}

